INSERT INTO `genres` VALUES (1,'Hành động','hanh-dong','Những pha rượt đuổi, cháy nổ và đối đầu nghẹt thở.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(2,'Phiêu lưu','phieu-luu','Hành trình khám phá những vùng đất mới.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(3,'Hoạt hình','hoat-hinh','Phim hoạt hình phù hợp cho cả gia đình.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(4,'Hài','hai','Tiếng cười sảng khoái sau giờ làm việc.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(5,'Kinh dị','kinh-di','Những câu chuyện rùng rợn, ám ảnh.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(6,'Khoa học viễn tưởng','khoa-hoc-vien-tuong','Tương lai, công nghệ và vũ trụ.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(7,'Tâm lý','tam-ly','Câu chuyện sâu lắng về con người và cuộc sống.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(8,'Tình cảm','tinh-cam','Những chuyện tình lãng mạn, cảm động.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(9,'Gia đình','gia-dinh','Phim phù hợp xem cùng người thân.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(10,'Tội phạm','toi-pham','Điều tra, phá án và thế giới ngầm.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(11,'Hồi hộp','hoi-hop','Căng thẳng, gay cấn đến phút cuối.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(12,'Bí ẩn','bi-an','Những câu đố và bí mật chờ được giải mã.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(13,'Giả tưởng','gia-tuong','Thế giới phép thuật và sinh vật kỳ ảo.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(14,'Lịch sử','lich-su','Tái hiện những sự kiện và nhân vật lịch sử.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(15,'Chiến tranh','chien-tranh','Khốc liệt nơi chiến trường.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(16,'Âm nhạc','am-nhac','Giai điệu và những câu chuyện âm nhạc.','2026-10-23 08:31:37','2026-10-23 08:31:37'),(17,'Tài liệu','tai-lieu','Câu chuyện có thật được ghi lại chân thực.','2026-10-23 08:31:37','2026-10-23 08:31:37');
/*!40000 ALTER TABLE `genres` ENABLE KEYS */;
